for (const item of $input.all()) {
  const { text } = item.json;

  const output = text.includes('<output>') && text.includes('</output>')
    ? text.split('<output>')[1].split('</output>')[0]
    : 'false';

  // The gate's reason for rejecting this draft. build_post_request puts it in
  // the next attempt's Reviewer Feedback block, and set_error_max_tries reports
  // it, so it is flattened to one line for both the prompt and the sheet cell.
  const explanation = text.includes('<explanation>') && text.includes('</explanation>')
    ? text.split('<explanation>')[1].split('</explanation>')[0].replace(/\s+/g, ' ').trim()
    : '';

  item.json.output = output;
  item.json.explanation = explanation;
}

return $input.all();

// n8n Code node — mode: "Run Once for Each Item"

const url = $('set_workflow_vars').item.json.URL;
const text = $json.text;

// Pull the <output>...</output> block; fall back to the whole text if absent
const match = /<output>([\s\S]*?)<\/output>/.exec(text);
let result = match ? match[1].trim() : text;

// The gate demands the exact placeholder, so it gets the line before any URL is rendered;
// substituting here first made every draft fail for the URL it had just been handed.
const review_text = result.replace(/^Source here:.*$/gm, 'Source here: SOME_URL');
result = review_text
  .replace(/(Source here: )SOME_URL/g, (m, p1) => p1 + url)
  .replace(/(.*): SOME_URL/g,   (m, p1) => p1 + ': ' + url);

return { json: { ...$json, review_text, result } };

// datasets/hook_types.json, parsed once. build_post_request reads byId to turn
// the row's HOOK id into the opening shape the registry declares for it.
const raw = $json.output || '{}';
let cfg;
try {
  cfg = JSON.parse(raw);
} catch (e) {
  throw new Error('datasets/hook_types.json is not valid JSON: ' + e.message);
}
const arr = (v, d) => (Array.isArray(v) ? v : d);
const str = (v) => String(v == null ? '' : v);
const byId = {};
for (const h of arr(cfg.hooks, [])) {
  if (h && h.id) byId[str(h.id).toUpperCase()] = h;
}
return [{ json: { byId } }];

// The post session is keyed on the article URL, not the sheet position: expiring rows
// renumbers the sheet, and a row number reused by a later article continued that
// article's session and its directives. The URL keeps a retry on the same article in
// one session and draws fresh directives for a new one.
const vars = $('main_trigger').first().json;
const url = String(vars.URL || '').trim();
if (!url) throw new Error('URL is required: the session id is derived from it');
const base = String($env.ARTICLE_WRITER_URL || '').replace(/\/+$/, '');
if (!base) throw new Error('ARTICLE_WRITER_URL is not set; the post session cannot be reached');
let h = 2166136261;
for (const ch of url) { h ^= ch.codePointAt(0); h = Math.imul(h, 16777619); }
const sessionId = 'post-' + (h >>> 0).toString(36);
// On a retry this node is fed by switch_check_rules_llm's retry output, so $json carries
// the gate's explanation; on the first attempt it carries the hook registry.
const explanation = String(($json && $json.explanation) || '').trim();
const feedback = [
  String(vars.FEEDBACK || '').trim(),
  explanation ? 'Internal review rejected the previous draft with: ' + explanation : '',
].filter(Boolean).join('\n');
// The hook is the curator's decision on the row; this graph only resolves its opening
// shape from the one registry, and the adapter formats the directive.
const byId = $('parse_hook_registry').first().json.byId || {};
const hookId = String(vars.HOOK || '').trim().toUpperCase();
const entry = byId[hookId] || null;
const brief = {
  content: String(vars.CONTENT || ''),
  url: String(vars.URL || 'https://www.alvsanand.com'),
  post_type: String(vars.POST_TYPE || 'LinkedIn Post'),
  min_words: Number(vars.MIN_WORDS) || 150,
  max_words: Number(vars.MAX_WORDS) || 200,
  extra_prompt: String(vars.EXTRA_PROMPT || ''),
  feedback,
  previous_post: String(vars.PREVIOUS_POST || '').trim(),
  hook: hookId,
  hook_opening: entry ? String(entry.opening || '') : '',
};
return [{ json: {
  SESSION_ID: sessionId,
  ATTEMPT: $runIndex + 1,
  POST_URL: base + '/v1/chat/completions',
  BRIEF: brief,
  POST_BODY: JSON.stringify({ lane: 'post', task: 'draft', session_id: sessionId, attempt: $runIndex + 1, brief }),
} }];

// The adapter answers {statusCode, body}; a refused turn is named here rather than parsed
// as an empty draft, and the text is rebuilt in the shape the two Code nodes below read.
const res = $input.first().json;
const status = Number(res.statusCode || res.status || 0);
const body = res.body && typeof res.body === 'object' ? res.body : {};
if (status >= 400) {
  const message = String((body.error && body.error.message) || body.error || body.message || '').trim();
  throw new Error('the post session refused the turn: HTTP ' + status + (message ? ': ' + message : ''));
}
const text = body && body.post && typeof body.post.text === 'string' ? body.post.text : '';
if (!text.trim()) throw new Error('the post session returned no post text');
return [{ json: { ...res, text } }];

// The gate is a writer turn too. It gets the draft n8n parsed, so it reviews exactly what
// this attempt produced; the same session carries the directives the drafter was given.
const parsed = $('parse_llm_output').first().json;
const req = $('build_post_request').first().json;
const text = String(parsed.review_text || '').trim();
if (!text) throw new Error('the gate has no post to review');
return [{ json: {
  POST_URL: req.POST_URL,
  POST_BODY: JSON.stringify({ lane: 'post', task: 'review', session_id: req.SESSION_ID, brief: req.BRIEF, post: { text } }),
} }];

